import { MakeLogicType, afterMount, connect, kea, path, selectors } from 'kea'
import { loaders } from 'kea-loaders'
import { subscriptions } from 'kea-subscriptions'

import { organizationLogic } from 'scenes/organizationLogic'
import { userLogic } from 'scenes/userLogic'

import type { OrganizationType, UserType } from '~/types'

import { type PipelineItem, comparePipelines, loadTeamPipelines } from '../shared/pipelineDiscovery'

export type PipelineTeamGroup = {
    teamId: number
    teamName: string
    items: PipelineItem[]
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface pipelineNotificationsLogicValues {
    currentOrganization: OrganizationType | null // organizationLogic
    user: UserType | null // userLogic
    allPipelineIds: string[]
    isPipelineDisabled: (pipelineId: string) => boolean
    pipelines: PipelineItem[]
    pipelinesByTeam: Record<string, PipelineTeamGroup>
    pipelinesLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface pipelineNotificationsLogicActions {
    loadPipelines: () => any
    loadPipelinesFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadPipelinesSuccess: (
        pipelines: PipelineItem[],
        payload?: any
    ) => {
        pipelines: PipelineItem[]
        payload?: any
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface pipelineNotificationsLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        allPipelineIds: (pipelines: PipelineItem[]) => string[]
        pipelinesByTeam: (pipelines: PipelineItem[]) => Record<string, PipelineTeamGroup>
        isPipelineDisabled: (user: UserType | null) => (pipelineId: string) => boolean
    }
}

export type pipelineNotificationsLogicType = MakeLogicType<
    pipelineNotificationsLogicValues,
    pipelineNotificationsLogicActions,
    Record<string, any>,
    pipelineNotificationsLogicMeta
>

export const pipelineNotificationsLogic = kea<pipelineNotificationsLogicType>([
    path(['scenes', 'settings', 'user', 'pipelineNotificationsLogic']),
    connect(() => ({
        values: [organizationLogic, ['currentOrganization'], userLogic, ['user']],
    })),
    loaders(({ values }) => ({
        pipelines: [
            [] as PipelineItem[],
            {
                loadPipelines: async () => {
                    const org: OrganizationType | null = values.currentOrganization
                    if (!org?.teams?.length) {
                        return []
                    }

                    const perTeamItems = await Promise.all(org.teams.map((team) => loadTeamPipelines(team)))

                    return perTeamItems
                        .flat()
                        .sort((a, b) => a.teamName.localeCompare(b.teamName) || comparePipelines(a, b))
                },
            },
        ],
    })),
    selectors({
        allPipelineIds: [(s) => [s.pipelines], (pipelines: PipelineItem[]): string[] => pipelines.map((p) => p.id)],
        pipelinesByTeam: [
            (s) => [s.pipelines],
            (pipelines: PipelineItem[]): Record<string, PipelineTeamGroup> =>
                pipelines.reduce(
                    (acc, pipeline) => {
                        const teamKey = `${pipeline.teamId}`
                        if (!acc[teamKey]) {
                            acc[teamKey] = {
                                teamId: pipeline.teamId,
                                teamName: pipeline.teamName,
                                items: [],
                            }
                        }
                        acc[teamKey].items.push(pipeline)
                        return acc
                    },
                    {} as Record<string, PipelineTeamGroup>
                ),
        ],
        isPipelineDisabled: [
            (s) => [s.user],
            (user: UserType | null) =>
                (pipelineId: string): boolean =>
                    !!user?.notification_settings?.pipeline_notifications_disabled?.[pipelineId],
        ],
    }),
    subscriptions(({ actions }) => ({
        currentOrganization: (curr: OrganizationType | null, prev: OrganizationType | null | undefined) => {
            if (curr?.id && curr.id !== prev?.id) {
                actions.loadPipelines()
            }
        },
    })),
    afterMount(({ actions, values }) => {
        if (values.currentOrganization?.teams?.length) {
            actions.loadPipelines()
        }
    }),
])
